const getValue = (variable, defaultValue = 0) => {
  const value = context.grafana.replaceVariables(variable);
  const numericValue = Number(value);
  return isNaN(numericValue) ? defaultValue : numericValue;
};

const gcpCosts = [
  getValue('$gcp12'), getValue('$gcp11'), getValue('$gcp10'),
  getValue('$gcp9'), getValue('$gcp8'), getValue('$gcp7'),
  getValue('$gcp6'), getValue('$gcp5'), getValue('$gcp4'),
  getValue('$gcp3'), getValue('$gcp2'), getValue('$gcp1'),
  getValue('$gcpAtual')
];

const budget = [
  getValue('56000'), getValue('56000'), getValue('56000'),
  getValue('56000'), getValue('56000'), getValue('56000'),
  getValue('56000'), getValue('56000'), getValue('56000'),
  getValue('56000'), getValue('56000'), getValue('56000'),
  getValue('56000')
];


const monthNames = ["Jan", "Fev", "Mar", "Abr", "Mai", "Jun", "Jul", "Ago", "Set", "Out", "Nov", "Dez"];
const currentMonth = new Date().getMonth();
const currentYear = new Date().getFullYear();
const months = [];

for (let i = 12; i >= 0; i--) {
  let monthIndex = (currentMonth - i + 12) % 12;
  let year = currentYear;
  if (currentMonth - i < 0) {
    year -= 1;
  }
  months.push(`${monthNames[monthIndex]}/${year.toString().slice(-2)}`);
}

const values = [["Cost", "Month", "Provider"]];

for (let i = 0; i < 13; i++) {
  values.push([gcpCosts[i], months[i], "GCP"]);
  values.push([budget[i], months[i], "Orçamento"]);
}

// Lista de provedores
const providers = ['GCP', 'Orçamento'];
const datasetWithFilters = [];
const seriesList = [];

context.echarts.util.each(providers, function (provider) {
  var datasetId = 'dataset_' + provider;

  // Define cor para cada provedor
  let color;
  switch (provider) {
    case 'AWS': color = '#FF9900'; break;
    case 'Azure': color = '#0078D4'; break;
    case 'GCP': color = '#34A853'; break;
    case 'OCI': color = '#F80000'; break;
    case 'Orçamento': color = '#F80000'; break;
  }

  datasetWithFilters.push({
    id: datasetId,
    fromDatasetId: 'dataset_raw',
    transform: {
      type: 'filter',
      config: {
        and: [{ dimension: 'Provider', '=': provider }]
      }
    }
  });

  const thresholdValue = 56000;

  seriesList.push({
    type: 'line',
    datasetId: datasetId,
    showSymbol: false,
    name: provider,
    lineStyle: { color: color, width: 3 },
    endLabel: {
      show: true,
      formatter: function (params) {
        // Formata o valor apenas como número com separadores de milhar, sem casas decimais
        const formattedValue = new Intl.NumberFormat('pt-BR', {
          style: 'currency',       // Formato de moeda
          currency: 'BRL',         // Define a moeda como Real
          minimumFractionDigits: 2,  // Sem casas decimais
          maximumFractionDigits: 2
        }).format(params.value[0]);
        return formattedValue;
      }
    },
    labelLayout: { moveOverlap: 'shiftY' },
    emphasis: { focus: 'series' },
    encode: {
      x: 'Month',
      y: 'Cost',
      label: ['Provider', 'Cost'],
      itemName: 'Month',
      tooltip: ['Cost']
    }
  });
});

// Configuração do gráfico
return {
  animationDuration: 3000,
  dataset: [
    { id: 'dataset_raw', source: values },
    ...datasetWithFilters
  ],
  grid: { left: '3%', right: '4%', bottom: '3%', containLabel: true },
  tooltip: {
    trigger: 'axis',
    axisPointer: {
      type: 'line',
      lineStyle: {
        color: function (params) {
          switch (params.seriesData[0].data[2]) {
            case 'AWS': return '#FF9900';
            case 'Azure': return '#0078D4';
            case 'GCP': return '#34A853';
            case 'OCI': return '#F80000';
            case 'Orçamento': return '#F80000';
            default: return '#000000';
          }
        }
      }
    },
    formatter: function (params) {
      let result = params[0].axisValue + '<br/>';
      params.forEach(function (item) {
        const color = item.seriesName === 'AWS' ? '#FF9900' :
          item.seriesName === 'Azure' ? '#0078D4' :
            item.seriesName === 'GCP' ? '#34A853' :
              item.seriesName === 'OCI' ? '#F80000' :
                item.seriesName === 'Orçamento' ? '#F80000' :
                  '#000000';
        result += '<span style="color:' + color + ';">●</span> ' +
          new Intl.NumberFormat('pt-BR', {
            style: 'currency',       // Formato de moeda
            currency: 'BRL',         // Define a moeda como Real
            minimumFractionDigits: 2,  // Sem casas decimais
            maximumFractionDigits: 2
          }).format(item.data[0]) + '<br/>';
      });
      return result;
    },
    textStyle: { color: '#000000' }
  },
  xAxis: {
    type: 'category',
    nameLocation: 'middle',
    data: months
  },
  yAxis: { name: '' },
  legend: {
    data: [{ name: 'GCP', icon: 'roundRect', textStyle: { color: '#d4d4d4' }, itemStyle: { color: '#34A853' } },
    { name: 'Orçamento', icon: 'roundRect', textStyle: { color: '#d4d4d4' }, itemStyle: { color: '#F80000' } }],
    top: '15px',
    left: 'center',
    selectedMode: 'multiple',
    textStyle: { color: '#000000' }
  },
  grid: { right: 80, left: 70, bottom: "50px" },
  series: seriesList
};
